import sys

MOD = 998244353

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    m = int(input[1])
    L = int(input[2])
    R = int(input[3])

    length = R - L + 1

    def pow_mod(base, exp):
        res = 1
        base %= MOD
        while exp > 0:
            if exp & 1:
                res = (res * base) % MOD
            base = (base * base) % MOD
            exp >>= 1
        return res

    class Matrix:
        def __init__(self, m):
            self.mat = m

        def multiply(self, other):
            r = [[0, 0], [0, 0]]
            for i in range(2):
                for j in range(2):
                    for k in range(2):
                        r[i][j] += self.mat[i][k] * other.mat[k][j]
                    r[i][j] %= MOD
            return Matrix(r)

        def pow(self, p):
            res = Matrix([[1, 0], [0, 1]])
            base = self
            while p > 0:
                if p & 1:
                    res = res.multiply(base)
                base = base.multiply(base)
                p >>= 1
            return res

    if n % 2 == 1 and m % 2 == 1:
        print(pow_mod(length % MOD, n * m))
    else:
        if length % 2 == 0:
            total = pow_mod(length % MOD, n * m - 1)
            answer = total * (length // 2) % MOD
            print(answer)
        else:
            half = length // 2
            identity = Matrix([[1, 0], [0, 1]])
            matrix = Matrix([[half, half + 1], [half + 1, half]])
            result_matrix = matrix.pow(n * m)
            print(result_matrix.mat[0][0])

if __name__ == "__main__":
    main()

